//! Minimal KVQP v1 writer from spec/10; generated bytes only, no trained payload.
use yskn_format::f32_to_f16;

#[derive(Clone, Default)]
pub struct Group {
    pub guard: u8,
    pub basis: Vec<[f32; 256]>,
    pub mean: Option<[f32; 256]>,
}

pub struct Profile {
    layers: u16,
    heads: u16,
    pub codes: [i16; 256],
    pub gain: f32,
    pub groups: Vec<Group>,
}
impl Profile {
    pub fn new(layers: u16, heads: u16) -> Self {
        Self {
            layers,
            heads,
            codes: std::array::from_fn(|s| ((s * 73 + 19) % 2049) as i16 - 1024),
            gain: 257.0 / 256.0,
            groups: vec![Group::default(); usize::from(layers) * usize::from(heads) * 2],
        }
    }

    pub fn bytes(&self) -> Vec<u8> {
        let mut bytes = vec![0; 108 + 4 * self.groups.len()];
        bytes[..4].copy_from_slice(b"KVQP");
        for (offset, value) in [
            (4, 1),
            (6, 96),
            (16, 256),
            (18, self.layers),
            (20, self.heads),
            (22, 1),
            (24, 1),
        ] {
            bytes[offset..offset + 2].copy_from_slice(&value.to_le_bytes());
        }
        put32(&mut bytes, 28, self.groups.len() as u32);
        for (offset, value) in [(32, 100), (36, 104), (40, 108)] {
            put32(&mut bytes, offset, value);
        }
        put32(&mut bytes, 100, 1.0f32.to_bits());
        let table = bytes.len();
        put32(&mut bytes, 104, table as u32);
        bytes.extend_from_slice(&[8, 0, 64, 8]);
        bytes.extend_from_slice(&self.gain.to_le_bytes());
        bytes.extend_from_slice(&[0; 4]);
        for code in self.codes {
            bytes.extend_from_slice(&code.to_le_bytes());
        }
        for (index, group) in self.groups.iter().enumerate() {
            let offset = bytes.len();
            put32(&mut bytes, 108 + 4 * index, offset as u32);
            bytes.extend_from_slice(&[
                0,
                5,
                0,
                group.guard,
                group.basis.len() as u8,
                u8::from(group.mean.is_some()),
                0,
                0,
            ]);
            for vector in group.mean.iter().chain(&group.basis) {
                for &value in vector {
                    bytes.extend_from_slice(&f32_to_f16(value).to_le_bytes());
                }
            }
        }
        let length = bytes.len();
        put32(&mut bytes, 8, length as u32);
        bytes
    }
}
fn put32(bytes: &mut [u8], offset: usize, value: u32) {
    bytes[offset..offset + 4].copy_from_slice(&value.to_le_bytes());
}

/// Two attention ordinals, two heads: first side pair packed; second values fallback.
pub fn mixed_profile() -> Vec<u8> {
    let mut profile = Profile::new(2, 2);
    profile.groups[0].mean = Some([0.125; 256]); // packed key mean
    profile.groups[1].mean = Some(std::array::from_fn(|i| (i as f32 - 128.0) / 1024.0));
    profile.groups[5].guard = 2;
    profile.groups[7].basis.push([0.0625; 256]);
    profile.groups[7].mean = Some([0.03125; 256]);
    profile.bytes()
}
